18	      --color-mode-2-rgb: 78, 205, 196;
19	      --color-mode-3-rgb: 149, 225, 211;
20	    }
21	
22	    * {
23	      margin: 0;
24	      padding: 0;
25	      box-sizing: border-box;
26	    }
27	    html {
28	      scroll-behavior: smooth;
29	    }
30	    html, body {
31	      width: 100%;
32	      height: 100%;
33	      overflow: hidden;
34	    }
35	    body {
36	      display: flex;
37	      flex-direction: column;
38	      justify-content: center;
39	      align-items: center;
40	      gap: 20px;
41	      background: linear-gradient(135deg, #5f6fd1 0%, #6b3fa0 100%);
42	      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
43	      color: var(--color-white);
44	      font-size: 14px;
45	      padding: 20px;
46	      min-height: 100vh;
47	    }
48	    .circle-container {
49	      cursor: pointer;
50	      border: none;
51	      background: none;
52	      padding: 0;
53	      position: relative;
54	      will-change: transform;
55	    }
