61	    }
62	    .circle-container:focus-visible {
63	      transform: scale(1.08);
64	      outline: 3px solid rgba(255, 255, 255, 0.7);
65	      outline-offset: 12px;
66	      border-radius: 50%;
67	    }
68	    svg {
69	      width: min(400px, 80vw);
70	      height: min(400px, 80vw);
71	      display: block;
72	      animation: fadeIn var(--transition-slow);
