148	      padding: 10px 20px;
149	      font-size: 12px;
150	      font-weight: 600;
151	      letter-spacing: 0.8px;
152	      text-transform: uppercase;
153	      background: rgba(255, 255, 255, 0.18);
154	      color: var(--color-white);
155	      border: 1.5px solid rgba(255, 255, 255, 0.35);
156	      border-radius: 24px;
