165	      background: rgba(255, 255, 255, 0.28);
166	      border-color: rgba(255, 255, 255, 0.6);
167	      transform: translateY(-3px);
168	      box-shadow: 0 10px 20px rgba(0, 0, 0, 0.25);
169	    }
