171	    .control-btn:active {
172	      transform: translateY(0) scale(0.96);
173	      box-shadow: 0 1px 2px rgba(0, 0, 0, 0.2);
174	    }
175	
176	    .control-btn:focus-visible {
177	      outline: 2px solid rgba(255, 255, 255, 0.7);
178	      outline-offset: 4px;
179	    }
180	    .control-btn:disabled {
181	      opacity: 0.5;
182	      cursor: not-allowed;
183	    }
184	    @keyframes pulse {
185	      0%, 100% { r: 200; opacity: 0.95; }
186	      50% { r: 203; opacity: 1; }
187	    }
188	    @keyframes pulse-active {
189	      0% { r: 200; }
190	      50% { r: 210; }
191	      100% { r: 200; }
192	    }
193	    @keyframes fadeIn {
194	      from { opacity: 0; transform: scale(0.9); }
195	      to { opacity: 1; transform: scale(1); }
196	    }
197	    @keyframes colorShift {
198	      0% { filter: saturate(1) brightness(1); }
199	      50% { filter: saturate(1.3) brightness(1.1); }
200	      100% { filter: saturate(1) brightness(1); }
201	    }
202	    .color-shifting circle {
203	      animation: colorShift 0.5s cubic-bezier(0.34, 1.56, 0.64, 1);
204	      transform-origin: center;
205	    }
206	    .keyboard-hint {
207	      font-size: 10px;
208	      opacity: 0.6;
209	      margin-top: 6px;
210	      letter-spacing: 0.3px;
211	      transition: opacity var(--transition-normal);
212	    }
213	    .keyboard-hint kbd {
214	      background: rgba(255, 255, 255, 0.15);
215	      border: 1px solid rgba(255, 255, 255, 0.25);
216	      border-radius: 3px;
217	      padding: 2px 6px;
218	      font-family: 'Monaco', 'Courier New', monospace;
219	      font-size: 9px;
220	      font-weight: 500;
221	      display: inline-block;
222	      margin: 0 2px;
223	    }
