261	        justify-content: center;
262	      }
263	    }
264	    @media (max-width: 360px) {
265	      body {
266	        gap: 8px;
267	        padding: 12px;
268	      }
269	      svg {
270	        width: min(280px, 70vw);
271	        height: min(280px, 70vw);
272	      }
