283	        padding: 3px 6px;
284	        font-size: 8px;
285	      }
286	    }
287	    @media (prefers-reduced-motion: reduce) {
288	      * {
289	        animation: none !important;
290	        transition: none !important;
291	      }
292	    }
293	    @supports (backdrop-filter: blur(0)) {
294	      .control-btn {
295	        background: rgba(255, 255, 255, 0.1);
296	      }
297	    }
