305	<body>
306	  <main>
307	    <button class="circle-container" id="decorative-circle" aria-label="Interactive circle - click to toggle" aria-pressed="false">
308	      <svg viewBox="0 0 400 400" width="400" height="400" aria-hidden="true" role="presentation">
309	        <circle cx="200" cy="200" r="200"/>
310	      </svg>
311	    </button>
312	    <div class="mode-indicator" id="mode-indicator" aria-live="polite" aria-atomic="true" aria-label="Current color mode"></div>
313	    <div class="controls" role="group" aria-label="Circle controls">
314	      <button class="control-btn" id="cycle-btn" aria-label="Cycle to next color">Cycle Color</button>
315	      <button class="control-btn" id="reset-btn" aria-label="Reset to default state">Reset</button>
316	    </div>
317	  </main>
318	  <div class="hint" id="hint-text" role="status" aria-live="polite" aria-relevant="text">Click to activate • Double-click to change color</div>
319	  <div class="keyboard-hint" aria-label="Keyboard shortcuts: Space or Enter to toggle, C to cycle color, R to reset">Press <kbd>C</kbd> to cycle • <kbd>R</kbd> to reset</div>
320	
321	  <script>
322	    const CONFIG = {
323	      storageKey: 'circle-state',
324	      tapDelay: 300,
325	      colorShiftDuration: 500,
326	      colorModes: [
327	        { class: 'default', name: 'Default White' },
328	        { class: 'color-mode-1', name: 'Pink' },
329	        { class: 'color-mode-2', name: 'Teal' },
330	        { class: 'color-mode-3', name: 'Mint' }
331	      ],
332	      isTouch: 'ontouchstart' in window || navigator.maxTouchPoints > 0
333	    };
334	
335	    const el = {
336	      circle: document.getElementById('decorative-circle'),
337	      hint: document.getElementById('hint-text'),
338	      modeIndicator: document.getElementById('mode-indicator'),
339	      cycleBtn: document.getElementById('cycle-btn'),
340	      resetBtn: document.getElementById('reset-btn')
341	    };
342	
343	    let state = { active: false, colorMode: 0 };
344	    let lastTapTime = 0;
345	    let tapTimeout = null;
346	    let animatingColorShift = false;
347	
348	    const getColorModeClass = (mode) => CONFIG.colorModes[mode].class;
349	    const getColorModeName = (mode) => CONFIG.colorModes[mode].name;
350	
351	    const storage = {
352	      save() {
353	        try {
354	          localStorage.setItem(CONFIG.storageKey, JSON.stringify(state));
355	        } catch {
356	          // Silently fail if localStorage is unavailable or quota exceeded
357	        }
358	      },
359	      load() {
360	        try {
361	          const saved = localStorage.getItem(CONFIG.storageKey);
362	          if (saved) {
363	            const parsed = JSON.parse(saved);
364	            if (parsed && typeof parsed === 'object') {
365	              state = { ...state, ...parsed };
366	            }
367	          }
368	        } catch {
369	          // Silently fail if parsing fails
370	        }
371	      }
372	    };
373	
374	    const updateClasses = () => {
375	      const colorClasses = CONFIG.colorModes.map(m => m.class);
376	      el.circle.classList.remove('active', ...colorClasses);
377	      el.circle.setAttribute('aria-pressed', state.active);
378	      if (state.active) el.circle.classList.add('active');
379	      if (state.colorMode > 0) el.circle.classList.add(getColorModeClass(state.colorMode));
380	    };
381	
382	    const updateUI = () => {
383	      const mainText = state.active ? 'Active!' : 'Click to activate';
384	      let hintParts = [mainText];
385	
386	      if (CONFIG.isTouch) {
387	        hintParts.push(state.active ? 'Tap to change color' : 'Tap twice to change color');
388	      } else {
389	        hintParts.push('Double-click to change color');
390	      }
391	
392	      el.hint.textContent = hintParts.join(' • ');
393	
394	      const showMode = state.active && state.colorMode > 0;
395	      el.modeIndicator.classList.toggle('visible', showMode);
396	      if (showMode) {
397	        const modeName = getColorModeName(state.colorMode);
398	        el.modeIndicator.textContent = modeName;
399	      }
400	    };
401	
402	    const applyState = () => {
403	      updateClasses();
404	      updateUI();
405	    };
406	
407	    const toggleActive = () => {
408	      state.active = !state.active;
409	      applyState();
410	      storage.save();
411	    };
412	
413	    const cycleColor = () => {
414	      if (animatingColorShift) return;
415	      animatingColorShift = true;
416	      state.colorMode = (state.colorMode + 1) % CONFIG.colorModes.length;
417	      state.active = true;
418	      el.circle.classList.add('color-shifting');
419	      setTimeout(() => {
420	        el.circle.classList.remove('color-shifting');
421	        animatingColorShift = false;
422	      }, CONFIG.colorShiftDuration);
423	      applyState();
424	      storage.save();
425	    };
426	
427	    const resetState = () => {
428	      state = { active: false, colorMode: 0 };
429	      applyState();
430	      storage.save();
431	    };
432	
433	    const handleDblClick = (e) => {
434	      e.preventDefault();
435	      cycleColor();
436	    };
437	
438	    const handleTouchEnd = (e) => {
439	      const now = Date.now();
440	      if (now - lastTapTime < CONFIG.tapDelay && lastTapTime > 0) {
441	        cycleColor();
442	        lastTapTime = 0;
443	        clearTimeout(tapTimeout);
444	      } else {
445	        lastTapTime = now;
446	        clearTimeout(tapTimeout);
447	        tapTimeout = setTimeout(() => { lastTapTime = 0; }, CONFIG.tapDelay);
448	      }
449	    };
450	
451	    const keyHandlers = {
452	      ' ': toggleActive,
453	      'enter': toggleActive,
454	      'c': cycleColor,
455	      'r': resetState
456	    };
457	
458	    const handleKeyDown = (e) => {
459	      const handler = keyHandlers[e.key.toLowerCase()];
460	      if (handler) {
461	        e.preventDefault();
462	        handler();
463	      }
464	    };
465	
466	    const initListeners = () => {
467	      el.circle.addEventListener('click', toggleActive);
468	      el.circle.addEventListener('dblclick', handleDblClick);
469	      el.circle.addEventListener('touchend', handleTouchEnd);
470	      el.circle.addEventListener('blur', () => {
471	        lastTapTime = 0;
472	        clearTimeout(tapTimeout);
473	      });
474	      document.addEventListener('keydown', handleKeyDown);
475	      el.cycleBtn.addEventListener('click', cycleColor);
476	      el.resetBtn.addEventListener('click', resetState);
477	    };
478	
479	    const initApp = () => {
480	      storage.load();
481	      applyState();
482	      initListeners();
483	      requestAnimationFrame(() => el.circle.focus());
484	    };
485	
486	    if (document.readyState === 'loading') {
487	      document.addEventListener('DOMContentLoaded', initApp);
488	    } else {
489	      initApp();
490	    }
491	  </script>
492	</body>
493	</html>
